unsigned long __cdecl file_load_fragment(const char *prefix, const char *suffix,
                                         void *destination,
                                         unsigned long byte_count)
{
    char filename[64];
    int handle;

    sprintf(filename, "%s%s", prefix, suffix);
    retry_open:
        handle = file_open_callback(filename, 0, 0);
        if (handle == -1) {
            dispatch_local_01000("Unable to open %s%s \n", prefix, suffix);
            return 0;
        }

        dispatch_local_01000("Loading %s @ 0x%x,size %d ", filename,
                             (unsigned long)destination, (int)byte_count);
        (void)file_read_callback(handle, destination, byte_count);
        if (file_close_callback(handle) != 0)
            goto retry_open;

    dispatch_local_01000("- Loaded \n");
    return 0;
}

